// Secure Express.js application with comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const sanitizeHtml = require('sanitize-html');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', apiLimiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Remove sensitive headers
app.disable('x-powered-by');

// ==================== INPUT VALIDATION HELPERS ====================

// Generic sanitization function
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return sanitizeHtml(input, {
      allowedTags: [], // Remove all HTML tags
      allowedAttributes: {},
    }).trim();
  }
  return input;
};

// Validation schemas
const schemas = {
  userQuery: Joi.object({
    id: Joi.number().integer().positive().optional(),
    name: Joi.string().trim().min(1).max(100).pattern(/^[a-zA-Z0-9\s\-_]+$/).optional(),
    email: Joi.string().email().optional(),
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
  }),
};

// ==================== CUSTOM ERROR CLASSES ====================

class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    // Capture stack trace
    Error.captureStackTrace(this, this.constructor);
  }
}

// ==================== MIDDLEWARE: VALIDATION & SANITIZATION ====================

// Middleware to validate and sanitize query parameters
const validateAndSanitizeQuery = (schema) => {
  return (req, res, next) => {
    try {
      // Sanitize all query parameters
      const sanitizedQuery = {};
      Object.keys(req.query).forEach(key => {
        sanitizedQuery[key] = sanitizeInput(req.query[key]);
      });
      req.query = sanitizedQuery;

      // Validate against schema
      const { error, value } = schema.validate(req.query, {
        abortEarly: false,
        stripUnknown: true, // Remove unknown fields
      });

      if (error) {
        const errorDetails = error.details.map(detail => ({
          field: detail.path.join('.'),
          message: detail.message,
        }));

        return next(new AppError(
          `Validation error: ${errorDetails.map(e => `${e.field}: ${e.message}`).join(', ')}`,
          400
        ));
      }

      // Replace query with validated values
      req.query = value;
      next();
    } catch (err) {
      next(err);
    }
  };
};

// ==================== ROUTES ====================

// Health check endpoint with security
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Secure users endpoint with validation
app.get('/api/users', 
  validateAndSanitizeQuery(schemas.userQuery),
  (req, res, next) => {
    try {
      const { id, name, email, limit, offset } = req.query;

      // Simulate filtered database query
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters based on validated parameters
      if (id) users = users.filter(u => u.id === id);
      if (name) users = users.filter(u => u.name.toLowerCase().includes(name.toLowerCase()));
      if (email) users = users.filter(u => u.email.toLowerCase().includes(email.toLowerCase()));

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        success: true,
        data: paginatedUsers,
        count: paginatedUsers.length,
        total: users.length,
        pagination: {
          limit,
          offset,
          hasMore: offset + limit < users.length
        }
      });
    } catch (err) {
      next(err);
    }
  }
);

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 404 handler for unknown routes
app.use('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Default values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Prepare error response
  const errorResponse = {
    success: false,
    status: err.status,
    message: err.message,
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  // For non-operational errors, send generic message in production
  if (!err.isOperational && process.env.NODE_ENV === 'production') {
    errorResponse.message = 'Something went wrong!';
  }

  res.status(err.statusCode).json(errorResponse);
});

// ==================== PROCESS HANDLERS ====================

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error('Error:', err);

  // Perform cleanup if needed
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  console.error('Error:', err);

  // Graceful shutdown
  server.close(() => {
    process.exit(1);
  });
});

// Handle SIGTERM for graceful shutdown
process.on('SIGTERM', () => {
  console.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.info('Process terminated');
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
